  makeArrow(v3(0, 0, FIG.f), v3(0, 1.05, FIG.f), FIG.green, vAxes, 0.20, 0.07);
  makeArrow(v3(0, 0, -FIG.f), v3(-1.05, 0, -FIG.f), FIG.green, rAxes, 0.20, 0.07);
