  bCoordScale: 1.15
};

const panelA = new THREE.Group();
const panelB = new THREE.Group();
scene.add(panelA);

const figureLabels = [];
let L = {};

const mats = {
  blackLine: new THREE.LineBasicMaterial({ color: FIG.black }),
  redLine: new THREE.LineBasicMaterial({ color: FIG.red }),
  greenLine: new THREE.LineBasicMaterial({ color: FIG.green }),
  blueLine: new THREE.LineBasicMaterial({ color: 0x1023ff }),
  grayLine: new THREE.LineBasicMaterial({ color: 0xb8c7c7, transparent: true, opacity: 0.78 }),
  rayDash: new THREE.LineDashedMaterial({ color: FIG.ray, dashSize: 0.20, gapSize: 0.13, transparent: true, opacity: 0.95 }),
  blackDash: new THREE.LineDashedMaterial({ color: FIG.black, dashSize: 0.22, gapSize: 0.13 }),
  planeV: new THREE.MeshBasicMaterial({ color: FIG.pale, side: THREE.DoubleSide, transparent: true, opacity: 0.45, depthWrite: false }),
  planeR: new THREE.MeshBasicMaterial({ color: FIG.dark, side: THREE.DoubleSide, transparent: true, opacity: 0.75, depthWrite: false }),
  cyan: new THREE.MeshBasicMaterial({ color: FIG.cyan }),
  black: new THREE.MeshBasicMaterial({ color: FIG.black })
};

function v3(x, y, z) { return new THREE.Vector3(x, y, z); }

function setGeomLine(line, pts) {
  const old = line.geometry;
  line.geometry = new THREE.BufferGeometry().setFromPoints(pts);
  old?.dispose?.();
  if (line.computeLineDistances) line.computeLineDistances();
}

function makeLine(pts, mat, parent = panelA) {
  const line = new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), mat);
  parent.add(line);
  if (mat.isLineDashedMaterial) line.computeLineDistances();
  return line;
}

function makeLoop(pts, mat, parent = panelA) {
  const line = new THREE.LineLoop(new THREE.BufferGeometry().setFromPoints(pts), mat);
  parent.add(line);
  if (mat.isLineDashedMaterial) line.computeLineDistances();
  return line;
}

function makeConeTip(pos, dir, color, parent, h = 0.22, r = 0.075) {
  const cone = new THREE.Mesh(new THREE.ConeGeometry(r, h, 28), new THREE.MeshBasicMaterial({ color }));
  const d0 = dir.clone().normalize();
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), d0);
  cone.position.copy(pos).addScaledVector(d0, -h / 2);
  parent.add(cone);
  return cone;
}

function makeArrow(start, end, color, parent = panelA, head = 0.23, rad = 0.075) {
  const g = new THREE.Group();
  parent.add(g);
  const dir = end.clone().sub(start).normalize();
  makeLine([start.clone(), end.clone().addScaledVector(dir, -head * 0.75)], new THREE.LineBasicMaterial({ color }), g);
  makeConeTip(end, dir, color, g, head, rad);
  return { group: g, start: start.clone(), end: end.clone(), color };
}

function makeDoubleArrow(start, end, color, parent = panelA, head = 0.22, rad = 0.075) {
  const g = new THREE.Group();
  parent.add(g);
  const dir = end.clone().sub(start).normalize();
  makeLine([start.clone().addScaledVector(dir, head * 0.75), end.clone().addScaledVector(dir, -head * 0.75)], new THREE.LineBasicMaterial({ color }), g);
  makeConeTip(end, dir, color, g, head, rad);
  makeConeTip(start, dir.clone().negate(), color, g, head, rad);
  return { group: g, start: start.clone(), end: end.clone(), color, head, rad };
}

function updateDoubleArrow(arrow, start, end) {
  while (arrow.group.children.length) arrow.group.remove(arrow.group.children[0]);
  const dir = end.clone().sub(start).normalize();
  makeLine([start.clone().addScaledVector(dir, arrow.head * 0.75), end.clone().addScaledVector(dir, -arrow.head * 0.75)], new THREE.LineBasicMaterial({ color: arrow.color }), arrow.group);
  makeConeTip(end, dir, arrow.color, arrow.group, arrow.head, arrow.rad);
  makeConeTip(start, dir.clone().negate(), arrow.color, arrow.group, arrow.head, arrow.rad);
  arrow.start.copy(start);
  arrow.end.copy(end);
}

function makePoint(parent, r = 0.085) {
  const g = new THREE.Group();
  const outer = new THREE.Mesh(new THREE.SphereGeometry(r * 1.42, 32, 16), mats.black);
  const inner = new THREE.Mesh(new THREE.SphereGeometry(r, 32, 16), mats.cyan);
  g.add(outer, inner);
  parent.add(g);
  return g;
}

function planeCorners(z, half = FIG.half) {
  return [
    v3(-half, -half, z),
    v3(half, -half, z),
    v3(half, half, z),
    v3(-half, half, z)
  ];
}

function farRectCorners() {
  return [
    v3(-1.55, -1.42, FIG.P.z),
    v3(2.35, -1.42, FIG.P.z),
    v3(2.35, 1.55, FIG.P.z),
    v3(-1.55, 1.55, FIG.P.z)
  ];
}

const worldAxes = new THREE.Group();
panelA.add(worldAxes);
makeArrow(v3(0, 0, 0), v3(3.2, 0, 0), FIG.black, worldAxes, 0.30, 0.10);
makeArrow(v3(0, 0, 0), v3(0, 3.6, 0), FIG.black, worldAxes, 0.30, 0.10);
makeArrow(v3(0, 0, 0), v3(0, 0, 5.7), FIG.black, worldAxes, 0.32, 0.105);

const pinhole = new THREE.Mesh(new THREE.SphereGeometry(0.11, 32, 16), mats.black);
pinhole.position.set(0, 0, 0);
