registerInteractive(pinhole, {
  title: 'Pinhole',
  tooltip: 'Pinhole at the world origin',
  body: 'All projection rays pass through the pinhole at O=(0,0,0). The two image planes are located at z=+f and z=-f.'
});

const physicalGroup = new THREE.Group();
const virtualGroup = new THREE.Group();
panelA.add(physicalGroup, virtualGroup);

const physicalPlane = new THREE.Mesh(new THREE.PlaneGeometry(FIG.half * 2, FIG.half * 2), mats.planeR);
physicalGroup.add(physicalPlane);
const virtualPlane = new THREE.Mesh(new THREE.PlaneGeometry(FIG.half * 2, FIG.half * 2), mats.planeV);
virtualGroup.add(virtualPlane);

const rOutline = makeLoop(planeCorners(-FIG.f), mats.blackDash, physicalGroup);
const vOutline = makeLoop(planeCorners(FIG.f), mats.blackLine, virtualGroup);

registerInteractive(physicalPlane, {
  title: 'Physical projection plane',
  tooltip: 'Real inverted sensor plane at z=-f',
  body: 'A real screen behind the pinhole records the sign-reversed point (-fX/Z,-fY/Z).'
});
registerInteractive(virtualPlane, {
  title: 'Virtual camera plane',
  tooltip: 'Upright virtual plane at z=+f',
  body: 'Computer vision usually uses this plane because the projected coordinates are upright: x=fX/Z and y=fY/Z.'
});

const pvPoint = makePoint(virtualGroup, 0.090);
const prPoint = makePoint(physicalGroup, 0.090);
const PPoint = makePoint(panelA, 0.095);
registerInteractive(PPoint, {
  title: 'Drag point P',
  tooltip: 'Drag P to change its world X and Y',
  body: 'Moving P changes the ray-plane intersection p. Its virtual camera coordinates are x=fX/Z and y=fY/Z.'
});

const rayLine = makeLine([FIG.P.clone(), v3(0, 0, 0)], mats.rayDash, panelA);
const auxVerticalP = makeLine([v3(0, 0, 0), v3(0, 0, 0)], mats.grayLine, panelA);
const auxUpperEdge = makeLine([v3(0, 0, 0), v3(0, 0, 0)], mats.grayLine, panelA);
const auxLowerEdge = makeLine([v3(0, 0, 0), v3(0, 0, 0)], mats.grayLine, panelA);
const auxFarEdge = makeLine([v3(0, 0, 0), v3(0, 0, 0)], mats.grayLine, panelA);

const fLeft = makeDoubleArrow(v3(0, 0, -FIG.f), v3(0, 0, 0), FIG.red, panelA, 0.24, 0.085);
const fRight = makeDoubleArrow(v3(0, 0, 0), v3(0, 0, FIG.f), FIG.red, panelA, 0.24, 0.085);

const vAxes = new THREE.Group();
const rAxes = new THREE.Group();
virtualGroup.add(vAxes);
physicalGroup.add(rAxes);

const farRect = makeLoop(farRectCorners(), mats.blackLine, panelA);
const farDrop = makeLine([v3(0, 0, 0), v3(0, 0, 0)], mats.grayLine, panelA);

