const bLeft = -bW / 2, bRight = bW / 2, bBot = -bH / 2, bTop = bH / 2;
makeLoop([v3(bLeft, bBot, 0), v3(bRight, bBot, 0), v3(bRight, bTop, 0), v3(bLeft, bTop, 0)], mats.blackLine, panelB);
const bPrincipal = v3(bLeft + 0.60 * bW, bBot + 0.48 * bH, 0);
const bCamAxes = new THREE.Group();
const bImgAxes = new THREE.Group();
panelB.add(bCamAxes, bImgAxes);
makeArrow(bPrincipal, bPrincipal.clone().add(v3(-1.35, 0, 0)), FIG.green, bCamAxes, 0.23, 0.082);
makeArrow(bPrincipal, bPrincipal.clone().add(v3(0, 1.25, 0)), FIG.green, bCamAxes, 0.23, 0.082);
const bImgOrigin = v3(bLeft, bBot, 0);
makeArrow(bImgOrigin, bImgOrigin.clone().add(v3(1.55, 0, 0)), 0x1023ff, bImgAxes, 0.23, 0.082);
makeArrow(bImgOrigin, bImgOrigin.clone().add(v3(0, 1.20, 0)), 0x1023ff, bImgAxes, 0.23, 0.082);
const bPPoint = makePoint(panelB, 0.085);

function cameraCoords() {
  const x = FIG.f * FIG.P.x / FIG.P.z;
  const y = FIG.f * FIG.P.y / FIG.P.z;
  const n = FIG.cn - x * FIG.s;
  const m = FIG.cm + y * FIG.s;
  return { x, y, n, m, pv: v3(x, y, FIG.f), pr: v3(-x, -y, -FIG.f) };
}

function rebuildPlaneAxes() {
  vAxes.clear();
  rAxes.clear();
  makeArrow(v3(0, 0, FIG.f), v3(1.08, 0, FIG.f), FIG.green, vAxes, 0.22, 0.078);
  makeArrow(v3(0, 0, FIG.f), v3(0, 1.08, FIG.f), FIG.green, vAxes, 0.22, 0.078);
  makeArrow(v3(0, 0, -FIG.f), v3(-1.08, 0, -FIG.f), FIG.green, rAxes, 0.22, 0.078);
  makeArrow(v3(0, 0, -FIG.f), v3(0, -1.08, -FIG.f), FIG.green, rAxes, 0.22, 0.078);
}

function updateGeometry() {
  const c = cameraCoords();

  virtualPlane.position.z = FIG.f;
  physicalPlane.position.z = -FIG.f;
  setGeomLine(vOutline, planeCorners(FIG.f));
  setGeomLine(rOutline, planeCorners(-FIG.f));
  rebuildPlaneAxes();

  pvPoint.position.copy(c.pv);
  prPoint.position.copy(c.pr);
  PPoint.position.copy(FIG.P);

  const convention = document.getElementById('projectionConvention').value;
  if (convention === 'Virtual upright') {
    setGeomLine(rayLine, [FIG.P.clone(), c.pv.clone(), v3(0, 0, 0)]);
  } else if (convention === 'Real inverted') {
    setGeomLine(rayLine, [FIG.P.clone(), v3(0, 0, 0), c.pr.clone()]);
  } else {
    setGeomLine(rayLine, [FIG.P.clone(), c.pv.clone(), v3(0, 0, 0), c.pr.clone()]);
  }

  const Pdrop = v3(FIG.P.x, c.pv.y, FIG.P.z);
  const upperOnPlane = v3(FIG.P.x, FIG.P.y, FIG.f);
  const lowerOnPlane = v3(c.pv.x, c.pv.y, FIG.f);
  setGeomLine(auxVerticalP, [FIG.P.clone(), Pdrop.clone()]);
  setGeomLine(auxUpperEdge, [FIG.P.clone(), upperOnPlane.clone()]);
  setGeomLine(auxLowerEdge, [Pdrop.clone(), lowerOnPlane.clone()]);
  setGeomLine(auxFarEdge, [upperOnPlane.clone(), c.pv.clone()]);
  setGeomLine(farRect, farRectCorners());
  setGeomLine(farDrop, [FIG.P.clone(), v3(FIG.P.x, c.pv.y, FIG.P.z)]);

  updateDoubleArrow(fLeft, v3(0, 0, -FIG.f), v3(0, 0, 0));
  updateDoubleArrow(fRight, v3(0, 0, 0), v3(0, 0, FIG.f));

  const bp = bPrincipal.clone().add(v3(-c.x * FIG.bCoordScale, c.y * FIG.bCoordScale, 0));
  bPPoint.position.copy(bp);

  if (L.projPlane) {
    L.projPlane.pos.set(-0.24, -2.00, -FIG.f);
    L.virtPlane.pos.set(0.30, -2.02, FIG.f);
    L.f1.pos.set(0, -0.30, -FIG.f / 2);
    L.f2.pos.set(0, -0.30, FIG.f / 2);
    L.pv.pos.copy(c.pv).add(v3(0.18, 0.22, 0));
    L.pr.pos.copy(c.pr).add(v3(-0.22, -0.26, 0));
    L.P.pos.copy(FIG.P).add(v3(0.02, 0.42, 0.02));
    L.vx.pos.set(1.20, 0.06, FIG.f);
    L.vy.pos.set(0.15, 1.22, FIG.f);
    L.rx.pos.set(-1.22, -0.08, -FIG.f);
    L.ry.pos.set(-0.15, -1.23, -FIG.f);
    L.bP.pos.copy(bp).add(v3(-0.28, -0.28, 0));
  }

  const read = document.getElementById('coordReadout');
  read.innerHTML =
    `<b>P</b> = (${FIG.P.x.toFixed(2)}, ${FIG.P.y.toFixed(2)}, ${FIG.P.z.toFixed(2)})<br>` +
    `<b>p camera</b> = (${c.x.toFixed(2)}, ${c.y.toFixed(2)})<br>` +
    `<b>image</b> (n,m) = (${Math.round(c.n)}, ${Math.round(c.m)})`;
  document.getElementById('focalLengthVal').textContent = FIG.f.toFixed(2);
  document.getElementById('pDepthVal').textContent = FIG.P.z.toFixed(2);
}

updateGeometry();

setCameraView({
