});

function lab(panel, feature, text, pos, opts = {}) {
  const entry = addLabel(text, pos, {
    fontSize: opts.fontSize || '24px',
    color: opts.color || '#111',
    bold: opts.bold || false,
    offset: opts.offset || [0, 0],
    background: opts.background
  });
  entry.panel = panel;
  entry.feature = feature;
  figureLabels.push(entry);
  return entry;
}

