};

updateGeometry();

function ensureActivePanelScene(isA) {
  if (isA) {
    if (panelB.parent) scene.remove(panelB);
    if (!panelA.parent) scene.add(panelA);
  } else {
    if (panelA.parent) scene.remove(panelA);
    if (!panelB.parent) scene.add(panelB);
  }
}

function updateVisibility() {
  const panel = document.getElementById('panelView').value;
  const conv = document.getElementById('projectionConvention').value;
  const isA = panel.startsWith('3D');
  ensureActivePanelScene(isA);

  physicalGroup.visible = conv === 'Both' || conv === 'Real inverted';
  virtualGroup.visible = conv === 'Both' || conv === 'Virtual upright';
  fLeft.group.visible = conv === 'Both' || conv === 'Real inverted';
  fRight.group.visible = conv === 'Both' || conv === 'Virtual upright';
  farRect.visible = farDrop.visible = auxVerticalP.visible = auxUpperEdge.visible = auxLowerEdge.visible = auxFarEdge.visible =
    conv === 'Both' || conv === 'Virtual upright';

  for (const item of figureLabels) {
    let show = item.panel === (isA ? 'A' : 'B');
    if (show && isA) {
      if (item.feature === 'physical') show = conv === 'Both' || conv === 'Real inverted';
      if (item.feature === 'virtual') show = conv === 'Both' || conv === 'Virtual upright';
    }
    item.div.style.visibility = show ? 'visible' : 'hidden';
  }

  if (isA) {
    setCameraView({
      projection: 'orthographic',
      axisScreenAngles: { x: 30, z: 30 },
      rollDeg: 0,
      heightFraction: 0.68,
      target: [0, 0.45, 1.65]
    });
  } else {
    setCameraView({
      projection: 'orthographic',
      axisScreenAngles: null,
      rollDeg: 0,
      heightFraction: 0.72,
      target: [0, -0.05, 0]
    });
  }
}

function applyAll() {
  FIG.f = parseFloat(document.getElementById('focalLength').value);
  FIG.P.z = Math.max(FIG.f + 0.5, parseFloat(document.getElementById('pDepth').value));
  document.getElementById('pDepth').value = FIG.P.z.toFixed(1);
  updateGeometry();
  updateVisibility();
}

document.getElementById('panelView').addEventListener('change', applyAll);
document.getElementById('projectionConvention').addEventListener('change', applyAll);
document.getElementById('focalLength').addEventListener('input', applyAll);
document.getElementById('pDepth').addEventListener('input', applyAll);

const dragRaycaster = new THREE.Raycaster();
const dragPointer = new THREE.Vector2();
let draggingP = false;
const dragPlane = new THREE.Plane(new THREE.Vector3(0, 0, 1), -FIG.P.z);
const dragHit = new THREE.Vector3();

function setDragPointer(event) {
  const rect = canvas.getBoundingClientRect();
  dragPointer.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
  dragPointer.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;
}

canvas.addEventListener('pointerdown', (event) => {
  if (!panelA.parent) return;
  setDragPointer(event);
  dragRaycaster.setFromCamera(dragPointer, camera);
  const hits = dragRaycaster.intersectObjects(PPoint.children, true);
  if (!hits.length) return;
  draggingP = true;
  controls.enabled = false;
  dragPlane.constant = -FIG.P.z;
  canvas.setPointerCapture?.(event.pointerId);
});

canvas.addEventListener('pointermove', (event) => {
  if (!draggingP) return;
  setDragPointer(event);
  dragRaycaster.setFromCamera(dragPointer, camera);
  if (dragRaycaster.ray.intersectPlane(dragPlane, dragHit)) {
    FIG.P.x = THREE.MathUtils.clamp(dragHit.x, -1.4, 1.4);
    FIG.P.y = THREE.MathUtils.clamp(dragHit.y, -1.2, 2.2);
    updateGeometry();
  }
});

window.addEventListener('pointerup', () => {
  if (!draggingP) return;
  draggingP = false;
  controls.enabled = true;
});

