function setDragPointer(event) {
  const rect = canvas.getBoundingClientRect();
  dragPointer.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
  dragPointer.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;
}

canvas.addEventListener('pointerdown', (event) => {
  if (!panelA.parent) return;
  setDragPointer(event);
  dragRaycaster.setFromCamera(dragPointer, camera);
  const hits = dragRaycaster.intersectObjects(PPoint.children, true);
  if (!hits.length) return;
  draggingP = true;
  controls.enabled = false;
  dragPlane.constant = -FIG.P.z;
  canvas.setPointerCapture?.(event.pointerId);
});

canvas.addEventListener('pointermove', (event) => {
  if (!draggingP) return;
  setDragPointer(event);
  dragRaycaster.setFromCamera(dragPointer, camera);
  if (dragRaycaster.ray.intersectPlane(dragPlane, dragHit)) {
    FIG.P.x = THREE.MathUtils.clamp(dragHit.x, -1.4, 1.4);
    FIG.P.y = THREE.MathUtils.clamp(dragHit.y, -1.2, 2.2);
    updateGeometry();
  }
});

window.addEventListener('pointerup', () => {
  if (!draggingP) return;
  draggingP = false;
  controls.enabled = true;
