  document.getElementById('projectionConvention').value = s.state.projectionConvention;
  tweenFocal(s.state.focalLength);
  document.getElementById('stepText').innerHTML = `<b>${stepIndex + 1}. ${s.title}</b><br>${s.narration}`;
};

document.getElementById('prevStep').addEventListener('click', () => window.goToStep(stepIndex - 1));
