    state: { panelView: '3D projection geometry (a)', focalLength: 3.5, projectionConvention: 'Real inverted' }
  }
];

let stepIndex = 0;
let focalTweenToken = 0;

function tweenFocal(target, ms = 650) {
  focalTweenToken++;
  const token = focalTweenToken;
  const start = FIG.f;
  const t0 = performance.now();

  function frame(t) {
    if (token !== focalTweenToken) return;
    const u = Math.min(1, (t - t0) / ms);
    const e = u < 0.5 ? 2 * u * u : 1 - Math.pow(-2 * u + 2, 2) / 2;
    const val = start + (target - start) * e;
    document.getElementById('focalLength').value = (Math.round(val * 4) / 4).toFixed(2);
    FIG.f = val;
    updateGeometry();
    updateVisibility();

    if (u < 1) {
      requestAnimationFrame(frame);
    } else {
      document.getElementById('focalLength').value = target;
      applyAll();
    }
  }
  requestAnimationFrame(frame);
}

window.goToStep = function goToStep(i) {
  stepIndex = THREE.MathUtils.clamp(i, 0, demoSteps.length - 1);
  const s = demoSteps[stepIndex];
  document.getElementById('panelView').value = s.state.panelView;
  document.getElementById('projectionConvention').value = s.state.projectionConvention;
  tweenFocal(s.state.focalLength);
  document.getElementById('stepText').innerHTML = `<b>${stepIndex + 1}. ${s.title}</b><br>${s.narration}`;
};

document.getElementById('prevStep').addEventListener('click', () => window.goToStep(stepIndex - 1));
document.getElementById('nextStep').addEventListener('click', () => window.goToStep(stepIndex + 1));

applyAll();
window.goToStep(0);
